    {
      "type": "text",
      "text": "For one bag, Gold adds 5 kg to the cabin allowance. You pay $15 for each kilogram over your allowance and nothing if the bag is at or below it."
    },
    {
      "type": "ui",
      "source": "root = Stack([cabin, status, weight, allowanceResult, feeResult])\n$cabin = 0\n$gold = 0\n$weight = 23\ncabin = Control(\"Cabin\", 0, 1, [\"Economy\", \"Business\"], $cabin)\nstatus = Control(\"Gold status\", 0, 1, [\"No Gold\", \"Gold\"], $gold)\nweight = Control(\"Bag weight (kg)\", 10, 40, [], $weight)\nbase = $cabin == 0 ? 23 : 32\nallowance = base + $gold * 5\nexcess = $weight > allowance ? $weight - allowance : 0\nallowanceResult = Metric(\"Bag allowance (kg)\", allowance)\nfeeResult = Metric(\"Single-bag fee ($)\", excess * 15)",
      "state": []
    }
  ]
}

